import React, { useState } from "react";
import {
  Plus,
  Search,
  Package,
  Pencil,
  Trash2,
  X,
} from "lucide-react";
import "./Products.css";

function Products() {
  const [products, setProducts] = useState([]);

  const [search, setSearch] = useState("");
  const [showModal, setShowModal] = useState(false);

  const [formData, setFormData] = useState({
    name: "",
    type: "Physical",
    salesPrice: "",
    costPrice: "",
    notes: "",
  });

  const handleChange = (e) => {
    const { name, value } = e.target;

    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    const newProduct = {
      id: Date.now(),
      ...formData,
    };

    setProducts((prev) => [...prev, newProduct]);

    setFormData({
      name: "",
      type: "Physical",
      salesPrice: "",
      costPrice: "",
      notes: "",
    });

    setShowModal(false);
  };

  const handleDelete = (id) => {
    const confirmDelete = window.confirm(
      "Are you sure you want to delete this product?"
    );

    if (confirmDelete) {
      setProducts((prev) => prev.filter((product) => product.id !== id));
    }
  };

  const filteredProducts = products.filter((product) =>
    product.name.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="products-page">
      {/* Header */}
      <div className="page-header products-header">
        <div>
          <h1>Products</h1>
          <p>Manage your products and pricing information.</p>
        </div>

        <button
          className="add-product-btn"
          onClick={() => setShowModal(true)}
        >
          <Plus size={18} />
          Add Product
        </button>
      </div>

      {/* Search */}
      <div className="products-toolbar">
        <div className="product-search">
          <Search size={18} />
          <input
            type="text"
            placeholder="Search products..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        <span>{filteredProducts.length} Products</span>
      </div>

      {/* Product Table */}
      <div className="products-table-container">
        <table className="products-table">
          <thead>
            <tr>
              <th>Product</th>
              <th>Type</th>
              <th>Sales Price</th>
              <th>Cost Price</th>
              <th>Notes</th>
              <th>Actions</th>
            </tr>
          </thead>

          <tbody>
            {filteredProducts.length > 0 ? (
              filteredProducts.map((product) => (
                <tr key={product.id}>
                  <td>
                    <div className="product-name-cell">
                      <div className="product-icon">
                        <Package size={18} />
                      </div>
                      <strong>{product.name}</strong>
                    </div>
                  </td>

                  <td>
                    <span className="product-type">
                      {product.type}
                    </span>
                  </td>

                  <td>₹{Number(product.salesPrice).toFixed(2)}</td>
                  <td>₹{Number(product.costPrice).toFixed(2)}</td>
                  <td>{product.notes || "—"}</td>

                  <td>
                    <div className="product-actions">
                      <button
                        type="button"
                        title="Edit"
                        onClick={() => alert("Edit feature is next.")}
                      >
                        <Pencil size={16} />
                      </button>

                      <button
                        type="button"
                        title="Delete"
                        onClick={() => handleDelete(product.id)}
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="6">
                  <div className="products-empty">
                    <Package size={36} />
                    <h3>No products found</h3>
                    <p>Add your first product to get started.</p>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Add Product Modal */}
      {showModal && (
        <div className="product-modal-overlay">
          <div className="product-modal">
            <div className="product-modal-header">
              <div>
                <h2>Add New Product</h2>
                <p>Enter your product details below.</p>
              </div>

              <button
                type="button"
                onClick={() => setShowModal(false)}
              >
                <X size={20} />
              </button>
            </div>

            <form onSubmit={handleSubmit}>
              <div className="product-form-group">
                <label>Product Name *</label>
                <input
                  type="text"
                  name="name"
                  placeholder="Enter product name"
                  value={formData.name}
                  onChange={handleChange}
                  required
                />
              </div>

              <div className="product-form-group">
                <label>Product Type *</label>
                <select
                  name="type"
                  value={formData.type}
                  onChange={handleChange}
                >
                  <option value="Physical">Physical</option>
                  <option value="Digital">Digital</option>
                  <option value="Service">Service</option>
                </select>
              </div>

              <div className="product-form-row">
                <div className="product-form-group">
                  <label>Sales Price (₹) *</label>
                  <input
                    type="number"
                    name="salesPrice"
                    min="0"
                    step="0.01"
                    placeholder="0.00"
                    value={formData.salesPrice}
                    onChange={handleChange}
                    required
                  />
                </div>

                <div className="product-form-group">
                  <label>Cost Price (₹) *</label>
                  <input
                    type="number"
                    name="costPrice"
                    min="0"
                    step="0.01"
                    placeholder="0.00"
                    value={formData.costPrice}
                    onChange={handleChange}
                    required
                  />
                </div>
              </div>

              <div className="product-form-group">
                <label>Notes</label>
                <textarea
                  name="notes"
                  placeholder="Additional product information..."
                  value={formData.notes}
                  onChange={handleChange}
                  rows="3"
                />
              </div>

              <div className="product-modal-actions">
                <button
                  type="button"
                  className="cancel-product-btn"
                  onClick={() => setShowModal(false)}
                >
                  Cancel
                </button>

                <button type="submit" className="save-product-btn">
                  Save Product
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default Products;
